package ai.pakostnik.demo;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import android.text.*;
import org.json.*;
import java.util.*;
import java.text.SimpleDateFormat;
import org.telegram.messenger.pakostnik.ConsolePalette;

/** Offline, explicitly labelled design playground. No Telegram or network implementation. */
public final class MainActivity extends Activity {
 private final String[] names={"Алексей","Марина","Дизайн проекта","Музыка"};
 private final String[] initials={"A","M","ДП","М"};
 private android.content.SharedPreferences prefs;
 private JSONArray conversations;
 private LinearLayout root,body;
 private String screen="Чаты";
 private int selected=-1,bg,accent,size,radius;
 private boolean mono;
 private Typeface font;
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("demo",0);loadProfile();try{conversations=new JSONArray(prefs.getString("chats",""));if(conversations.length()!=4)throw new Exception();}catch(Exception e){seed();}if(state!=null){screen=state.getString("screen","Чаты");selected=state.getInt("selected",-1);if(selected<0||selected>3)selected=-1;}render();}
 @Override public void onSaveInstanceState(Bundle state){state.putString("screen",screen);state.putInt("selected",selected);super.onSaveInstanceState(state);}
 private void loadProfile(){bg=prefs.getInt("bg",0xff000000);accent=prefs.getInt("accent",0xffeeeeee);size=prefs.getInt("size",16);radius=prefs.getInt("radius",0);mono=prefs.getBoolean("mono",true);font=mono?Typeface.MONOSPACE:Typeface.DEFAULT;}
 private JSONObject message(String text,boolean out,String kind,boolean deleted){try{return new JSONObject().put("text",text).put("out",out).put("kind",kind).put("deleted",deleted).put("time",new SimpleDateFormat("HH:mm",Locale.ROOT).format(new Date()));}catch(Exception e){throw new IllegalStateException(e);}}
 private void seed(){conversations=new JSONArray();try{for(int i=0;i<4;i++){JSONArray list=new JSONArray();if(i==0){list.put(message("Привет! Это тестовая переписка.",false,"text",false));list.put(message("Проверяю Pakostnik.",true,"text",false));list.put(message("Встречаемся в семь?",false,"text",true));list.put(message("Голосовое • 0:18",false,"voice",false));list.put(message("Кружок • 0:12",false,"video",false));list.put(message("project.zip • 1,2 МБ",false,"file",false));}else list.put(message(new String[]{"","Привет! Как настроение?","Макеты готовы к обсуждению.","Новый альбом уже вышел."}[i],false,"text",false));conversations.put(new JSONObject().put("mode",0).put("messages",list));}}catch(Exception e){throw new IllegalStateException(e);}persist();}
 private JSONObject chat(){return conversations.optJSONObject(selected);}
 private JSONArray messages(){return chat().optJSONArray("messages");}
 private void persist(){prefs.edit().putString("chats",conversations.toString()).apply();}
 private TextView text(String s,int sp,int color){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(sp);t.setTypeface(font);t.setIncludeFontPadding(false);return t;}
 private GradientDrawable shape(int color,int corner){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(corner));return d;}
 private TextView button(String label,Runnable action){TextView b=text(label,13,accent);b.setGravity(Gravity.CENTER);b.setPadding(dp(12),dp(14),dp(12),dp(14));b.setBackground(shape(ConsolePalette.surface(bg,.065),4));b.setOnClickListener(v->action.run());b.setContentDescription(label);return b;}
 private void gap(LinearLayout parent,int h){Space s=new Space(this);parent.addView(s,new LinearLayout.LayoutParams(1,dp(h)));}
 private void line(LinearLayout parent){View v=new View(this);v.setBackgroundColor(0xff292929);parent.addView(v,new LinearLayout.LayoutParams(-1,dp(1)));}
 private void hint(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void go(String page){selected=-1;screen=page;render();}
 private void render(){
  loadProfile();getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);
  root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);
  root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());Insets ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(16),dp(14),dp(16),dp(14));
  TextView left=text(selected>=0?"‹":"≡",26,accent);left.setPadding(0,0,dp(16),0);left.setContentDescription(selected>=0?"Назад":"Меню");left.setOnClickListener(v->{if(selected>=0){selected=-1;screen="Чаты";render();}else go("Меню");});header.addView(left);
  TextView title=text(selected>=0?names[selected]:screen.equals("Чаты")?"PAKOSTNIK_":screen,20,0xffeeeeee);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));
  TextView settings=text("⚙",24,accent);settings.setContentDescription("Оформление");settings.setOnClickListener(v->go("Оформление"));header.addView(settings);root.addView(header);
  TextView demo=text("DEMO / тестовые данные / без Telegram",10,0xff999999);demo.setPadding(dp(18),0,dp(18),dp(12));root.addView(demo);line(root);
  body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
  if(selected>=0)renderChat();else{switch(screen){case "Контакты":contacts();break;case "Звонки":calls();break;case "Меню":menu();break;case "Оформление":appearance();break;case "Pakostnik AI":aiSettings();break;default:chatList();}}
  if(selected<0){line(root);LinearLayout nav=new LinearLayout(this);for(String item:new String[]{"Чаты","Контакты","Звонки","Меню"}){TextView tab=text(item,11,item.equals(screen)?accent:0xff777777);tab.setGravity(Gravity.CENTER);tab.setPadding(0,dp(18),0,dp(18));tab.setOnClickListener(v->go(item));nav.addView(tab,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);}
 }
 private LinearLayout scroll(LinearLayout parent){ScrollView s=new ScrollView(this);s.setFillViewport(true);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(14),dp(16),dp(18));s.addView(box);parent.addView(s,new LinearLayout.LayoutParams(-1,0,1));return box;}
 private void section(LinearLayout box,String s){TextView label=text(s,12,accent);label.setPadding(0,dp(16),0,dp(12));box.addView(label);}
 private EditText input(String placeholder,String value){EditText e=new EditText(this);e.setTextColor(0xffeeeeee);e.setHintTextColor(0xff777777);e.setHint(placeholder);e.setTypeface(font);e.setTextSize(size);e.setSingleLine(true);e.setText(value);e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));return e;}
 private void chatList(){
  EditText search=input("/ поиск по тестовым чатам","");search.setPadding(dp(16),dp(12),dp(16),dp(12));body.addView(search);
  LinearLayout box=scroll(body);fillChats(box,"");search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){fillChats(box,s.toString());}public void afterTextChanged(Editable e){}});
 }
 private void fillChats(LinearLayout box,String filter){box.removeAllViews();for(int i=0;i<names.length;i++){if(!names[i].toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))continue;final int index=i;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(18),0,dp(18));TextView avatar=text(initials[i],18,accent);avatar.setGravity(Gravity.CENTER);avatar.setBackground(shape(ConsolePalette.surface(bg,.09),28));row.addView(avatar,new LinearLayout.LayoutParams(dp(50),dp(50)));LinearLayout details=new LinearLayout(this);details.setOrientation(LinearLayout.VERTICAL);details.setPadding(dp(14),0,0,0);details.addView(text(names[i],size,0xffeeeeee));JSONArray list=conversations.optJSONObject(i).optJSONArray("messages");JSONObject last=list.optJSONObject(list.length()-1);TextView preview=text(last.optString("text"),12,0xff999999);preview.setSingleLine(true);preview.setEllipsize(TextUtils.TruncateAt.END);gap(details,8);details.addView(preview);row.addView(details,new LinearLayout.LayoutParams(0,-2,1));row.addView(text(last.optString("time"),10,0xff777777));row.setOnClickListener(v->{selected=index;render();});box.addView(row);line(box);}}
 private void renderChat(){
  LinearLayout modeRow=new LinearLayout(this);modeRow.setPadding(dp(12),dp(8),dp(12),dp(8));int mode=chat().optInt("mode");TextView modeButton=button(new String[]{"Ручной / демо","Помощник / демо","Автопилот / демо"}[mode],()->new AlertDialog.Builder(this).setTitle("Режим тестового чата").setItems(new String[]{"Ручной","Помощник","Автопилот"},(d,n)->{try{chat().put("mode",n);}catch(Exception ignored){}persist();render();}).show());modeRow.addView(modeButton,new LinearLayout.LayoutParams(-1,-2));body.addView(modeRow);
  LinearLayout box=scroll(body);ScrollView scroller=(ScrollView)box.getParent();JSONArray list=messages();for(int i=0;i<list.length();i++)bubble(box,list.optJSONObject(i),i);box.post(()->scroller.fullScroll(View.FOCUS_DOWN));
  LinearLayout controls=new LinearLayout(this);controls.setPadding(dp(12),dp(6),dp(12),dp(6));controls.addView(button("+ входящее",this::incoming),new LinearLayout.LayoutParams(0,-2,1));Space spacer=new Space(this);controls.addView(spacer,new LinearLayout.LayoutParams(dp(6),1));controls.addView(button("✕ удаление",this::deleteIncoming),new LinearLayout.LayoutParams(0,-2,1));body.addView(controls);
  LinearLayout composer=new LinearLayout(this);composer.setGravity(Gravity.CENTER_VERTICAL);composer.setPadding(dp(14),dp(4),dp(14),dp(12));TextView attach=text("+",26,accent);attach.setPadding(0,0,dp(12),0);attach.setContentDescription("Пример медиа");attach.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Тестовые вложения").setItems(new String[]{"Фото","Документ","Голосовое","Кружок"},(d,n)->{String[] kinds={"photo","file","voice","video"};String[] labels={"Тестовое фото","example.pdf • 280 КБ","Голосовое • 0:18","Кружок • 0:12"};messages().put(message(labels[n],true,kinds[n],false));persist();render();}).show());composer.addView(attach);
  EditText edit=input("Сообщение_","");composer.addView(edit,new LinearLayout.LayoutParams(0,-2,1));TextView send=button(">",()->{String value=edit.getText().toString().trim();if(value.isEmpty())return;if(value.length()>4000){hint("До 4000 символов в демо");return;}messages().put(message(value,true,"text",false));trim();persist();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(edit.getWindowToken(),0);render();});send.setContentDescription("Добавить сообщение в демо");composer.addView(send);body.addView(composer);
 }
 private void trim(){JSONArray a=messages();while(a.length()>200)a.remove(0);}
 private void incoming(){messages().put(message("Это новое тестовое входящее сообщение.",false,"text",false));int mode=chat().optInt("mode");trim();persist();render();if(mode==2){messages().put(message("Принял, спасибо! Это локальный демонстрационный ответ.",true,"text",false));persist();render();}else if(mode==1)new AlertDialog.Builder(this).setTitle("Предложение / демо").setMessage("Принял, спасибо!").setPositiveButton("Добавить в тестовый чат",(d,w)->{messages().put(message("Принял, спасибо!",true,"text",false));persist();render();}).setNegativeButton("Отмена",null).show();}
 private void deleteIncoming(){for(int i=messages().length()-1;i>=0;i--){JSONObject m=messages().optJSONObject(i);if(!m.optBoolean("out")&&!m.optBoolean("deleted")){try{m.put("deleted",true);}catch(Exception ignored){}persist();render();return;}}hint("Нет входящего сообщения для тестового удаления");}
 private void bubble(LinearLayout box,JSONObject m,int index){boolean out=m.optBoolean("out");LinearLayout outer=new LinearLayout(this);outer.setGravity(out?Gravity.RIGHT:Gravity.LEFT);outer.setPadding(0,dp(4),0,dp(4));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(10),dp(12),dp(8));card.setBackground(shape(ConsolePalette.surface(bg,out?.13:.065),radius));String kind=m.optString("kind");if(kind.equals("voice")||kind.equals("video")||kind.equals("photo")){MediaView media=new MediaView(kind);card.addView(media,new LinearLayout.LayoutParams(dp(kind.equals("video")?140:230),dp(kind.equals("voice")?52:140)));media.setOnClickListener(v->hint("Это визуальный пример. Запись и воспроизведение медиа в демо не подключены."));}else{TextView content=text((kind.equals("file")?"↓ ":"")+m.optString("text"),size,0xffeeeeee);content.setMaxWidth(dp(265));content.setTextIsSelectable(true);card.addView(content);if(kind.equals("file"))content.setOnClickListener(v->hint("Это тестовая карточка файла, скачивание не выполняется."));}TextView time=text((m.optBoolean("deleted")?"✕ удалено · ":"")+m.optString("time")+(out?" ✓✓":""),10,m.optBoolean("deleted")?accent:0xff888888);time.setPadding(0,dp(8),0,0);time.setGravity(Gravity.RIGHT);card.addView(time);if(!out)card.setOnLongClickListener(v->{try{m.put("deleted",true);}catch(Exception ignored){}persist();render();return true;});outer.addView(card);box.addView(outer);}
 private void contacts(){LinearLayout box=scroll(body);section(box,"КОНТАКТЫ / ТЕСТОВЫЕ");for(int i=0;i<names.length;i++){final int n=i;box.addView(button(names[i],()->{selected=n;render();}));gap(box,8);}box.addView(text("Контакты телефона не запрашиваются.",12,0xff999999));}
 private void calls(){LinearLayout box=scroll(body);section(box,"ЗВОНКИ / ПРИМЕР СПИСКА");box.addView(text("↙ Алексей · сегодня, 14:20\n\n↗ Марина · вчера, 19:40",size,0xffeeeeee));gap(box,20);box.addView(button("Тест кнопки звонка",()->hint("Настоящие звонки доступны в основном клиенте после подключения Telegram.")));}
 private void menu(){LinearLayout box=scroll(body);section(box,"PAKOSTNIK / CONTROL");for(String name:new String[]{"Оформление","Pakostnik AI","Контакты","Звонки"}){box.addView(button(name,()->go(name)));gap(box,10);}section(box,"О ДЕМОВЕРСИИ");box.addView(text("Автономный пример интерфейса. Нет входа в аккаунт, доступа к Telegram, настоящего ИИ, записи или отправки медиа. Всё хранится только в этом приложении.",13,0xff999999));gap(box,20);box.addView(button("Сбросить тестовые переписки",()->new AlertDialog.Builder(this).setMessage("Удалить локальные тестовые сообщения?").setPositiveButton("Сбросить",(d,w)->{seed();go("Чаты");}).setNegativeButton("Отмена",null).show()));}
 private void aiSettings(){LinearLayout box=scroll(body);section(box,"AI / ЛОКАЛЬНАЯ ИМИТАЦИЯ");box.addView(text("Проверь режимы на тестовых сообщениях. В открытом чате выбери режим и нажми «+ входящее». Ответы заранее заданы, к ИИ-сервису приложение не подключается.",size,0xffeeeeee));gap(box,20);box.addView(button("Открыть тестовый чат",()->{selected=0;render();}));}
 private void appearance(){
  LinearLayout box=scroll(body);section(box,"APPEARANCE / CONSOLE");EditText bgInput=input("Фон #RRGGBB",ConsolePalette.hex(bg));EditText accentInput=input("Акцент #RRGGBB",ConsolePalette.hex(accent));box.addView(text("Фон",13,0xff999999));box.addView(bgInput);box.addView(text("Акцент",13,0xff999999));box.addView(accentInput);
  Switch fontSwitch=new Switch(this);fontSwitch.setText("Моноширинный шрифт");fontSwitch.setTextColor(0xffeeeeee);fontSwitch.setTypeface(font);fontSwitch.setChecked(mono);fontSwitch.setThumbTintList(android.content.res.ColorStateList.valueOf(accent));box.addView(fontSwitch);
  TextView fontLabel=text("Размер текста: "+size,13,0xff999999);box.addView(fontLabel);SeekBar fontSeek=new SeekBar(this);fontSeek.setMax(12);fontSeek.setProgress(size-12);fontSeek.setThumbTintList(android.content.res.ColorStateList.valueOf(accent));fontSeek.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));box.addView(fontSeek);
  TextView curveLabel=text("Скругление: "+radius,13,0xff999999);box.addView(curveLabel);SeekBar curve=new SeekBar(this);curve.setMax(18);curve.setProgress(radius);curve.setThumbTintList(android.content.res.ColorStateList.valueOf(accent));curve.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));box.addView(curve);
  TextView preview=text("> Привет!\n> Встречаемся в семь?\n  ✕ удалено · 14:24\n\n> Сообщение_",size,accent);preview.setPadding(dp(16),dp(16),dp(16),dp(16));box.addView(preview);
  Runnable update=()->{fontLabel.setText("Размер текста: "+(12+fontSeek.getProgress()));curveLabel.setText("Скругление: "+curve.getProgress());preview.setTextSize(12+fontSeek.getProgress());preview.setTypeface(fontSwitch.isChecked()?Typeface.MONOSPACE:Typeface.DEFAULT);try{int b=ConsolePalette.parse(bgInput.getText().toString()),a=ConsolePalette.parse(accentInput.getText().toString());ConsolePalette.validate(b,a);preview.setTextColor(a);preview.setBackground(shape(ConsolePalette.surface(b,.065),curve.getProgress()));}catch(Exception ignored){}};
  SeekBar.OnSeekBarChangeListener listener=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){update.run();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}};fontSeek.setOnSeekBarChangeListener(listener);curve.setOnSeekBarChangeListener(listener);fontSwitch.setOnCheckedChangeListener((b,value)->update.run());TextWatcher watch=new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){update.run();}public void afterTextChanged(Editable e){}};bgInput.addTextChangedListener(watch);accentInput.addTextChangedListener(watch);update.run();gap(box,16);
  box.addView(button("Чёрно-белая консоль",()->{bgInput.setText("#000000");accentInput.setText("#EEEEEE");fontSwitch.setChecked(true);curve.setProgress(0);update.run();}));gap(box,8);box.addView(button("Зелёный терминал",()->{bgInput.setText("#000000");accentInput.setText("#A6FF80");fontSwitch.setChecked(true);update.run();}));gap(box,8);
  box.addView(button("Применить",()->{try{int b=ConsolePalette.parse(bgInput.getText().toString()),a=ConsolePalette.parse(accentInput.getText().toString());ConsolePalette.validate(b,a);prefs.edit().putInt("bg",b).putInt("accent",a).putBoolean("mono",fontSwitch.isChecked()).putInt("size",12+fontSeek.getProgress()).putInt("radius",curve.getProgress()).apply();render();hint("Оформление сохранено");}catch(Exception e){hint("Нужны тёмный фон и контрастный акцент в формате #RRGGBB");}}));
 }
 @Override public void onBackPressed(){if(selected>=0){selected=-1;screen="Чаты";render();}else if(!screen.equals("Чаты"))go("Чаты");else super.onBackPressed();}
 private final class MediaView extends View {
  private final String kind;private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);
  MediaView(String kind){super(MainActivity.this);this.kind=kind;setContentDescription("Демонстрационная карточка: "+kind);}
  @Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();p.setColor(0xff222222);if(kind.equals("video"))c.drawCircle(w/2,h/2,Math.min(w,h)/2-2,p);else c.drawRect(0,0,w,h,p);p.setColor(accent);p.setStrokeWidth(dp(2));if(kind.equals("voice")){Path tri=new Path();tri.moveTo(dp(12),h/2-dp(10));tri.lineTo(dp(12),h/2+dp(10));tri.lineTo(dp(27),h/2);tri.close();c.drawPath(tri,p);for(int i=0;i<25;i++){float x=dp(40)+i*(w-dp(52))/25;float height=dp(3+(i*7)%18);c.drawLine(x,h/2-height/2,x,h/2+height/2,p);}}else{c.save();if(kind.equals("video")){Path clip=new Path();clip.addCircle(w/2,h/2,Math.min(w,h)/2-2,Path.Direction.CW);c.clipPath(clip);}p.setColor(0xff555555);Path hills=new Path();hills.moveTo(0,h);hills.lineTo(0,h*.75f);hills.lineTo(w*.3f,h*.35f);hills.lineTo(w*.6f,h*.72f);hills.lineTo(w*.82f,h*.46f);hills.lineTo(w,h*.8f);hills.lineTo(w,h);hills.close();c.drawPath(hills,p);p.setColor(0xffaaaaaa);c.drawCircle(w*.72f,h*.26f,dp(12),p);c.restore();}p.setColor(0xffeeeeee);p.setTypeface(font);p.setTextSize(dp(10));if(!kind.equals("voice"))c.drawText(kind.equals("video")?"DEMO 0:12":"DEMO PHOTO",dp(12),h-dp(12),p);}
 }
}
